import { ParameterSpecRecord } from "#base/scripts/voronoi-types.js";
import { RuleAvoidEdge } from "#base/scripts/voronoi_rules/avoid-edge.js";
import { RuleAvoidOtherRegions } from "#base/scripts/voronoi_rules/avoid-other-regions.js";
import { RuleCellArea } from "#base/scripts/voronoi_rules/cell-area.js";
import { RuleCoastalExposure } from "#base/scripts/voronoi_rules/coastal-exposure.js";
import { RuleNearMapCenter } from "#base/scripts/voronoi_rules/near-map-center.js";
import { RuleNearNeighbor } from "#base/scripts/voronoi_rules/near-neighbor.js";
import { RuleNearOtherRegion } from "#base/scripts/voronoi_rules/near-other-region.js";
import { RuleNearPlateBoundary } from "#base/scripts/voronoi_rules/near-plate-boundary.js";
import { RuleNearRegionSeed } from "#base/scripts/voronoi_rules/near-region-seed.js";
import { RuleNeighborsInRegion } from "#base/scripts/voronoi_rules/neighbors-in-region.js";
import { RulePreferLatitude } from "#base/scripts/voronoi_rules/prefer-latitude.js";
import { Rule } from "#base/scripts/voronoi_rules/rules-base.js";

// Rules

export type RuleCtor<T extends Rule = Rule> = new () => T;

const ruleRegistry: Record<string, [RuleCtor, ParameterSpecRecord]> = {
	[RuleAvoidEdge.getName()]: [RuleAvoidEdge, RuleAvoidEdge.getSchema()],
	[RuleAvoidOtherRegions.getName()]: [RuleAvoidOtherRegions, RuleAvoidOtherRegions.getSchema()],
	[RuleCellArea.getName()]: [RuleCellArea, RuleCellArea.getSchema()],
	[RuleNearMapCenter.getName()]: [RuleNearMapCenter, RuleNearMapCenter.getSchema()],
	[RuleNearNeighbor.getName()]: [RuleNearNeighbor, RuleNearNeighbor.getSchema()],
	[RuleNearOtherRegion.getName()]: [RuleNearOtherRegion, RuleNearOtherRegion.getSchema()],
	[RuleNearPlateBoundary.getName()]: [RuleNearPlateBoundary, RuleNearPlateBoundary.getSchema()],
	[RuleNearRegionSeed.getName()]: [RuleNearRegionSeed, RuleNearRegionSeed.getSchema()],
	[RuleNeighborsInRegion.getName()]: [RuleNeighborsInRegion, RuleNeighborsInRegion.getSchema()],
	[RulePreferLatitude.getName()]: [RulePreferLatitude, RulePreferLatitude.getSchema()],
	[RuleCoastalExposure.getName()]: [RuleCoastalExposure, RuleCoastalExposure.getSchema()],
};

export function RegisterRule(name: string, ctor: RuleCtor, schema: ParameterSpecRecord) {
	ruleRegistry[name] = [ctor, schema];
}
export function ConstructRule(name: string): Rule {
	if (!(name in ruleRegistry)) throw new Error(`Cannot find rule ${name} in rule registry.`);
	return new ruleRegistry[name][0]();
}
export function GetRuleSpec(name: string): ParameterSpecRecord {
	if (!(name in ruleRegistry)) throw new Error(`Cannot find rule ${name} in rule registry.`);
	return ruleRegistry[name][1];
}
